{
  "name": "shop-api",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "sync": "node --env-file=.env src/sync.js",
    "weather-check": "bash scripts/weather-check.sh"
  },
  "dependencies": {
    "axios": "1.20.0"
  }
}
#!/bin/bash
# Checks that the weather API accepts our key.
set -a; [ -f .env ] && . ./.env; set +a
status=$(curl -sv --max-time 15 -o /dev/null -w "%{http_code}" \
  -H "Authorization: Bearer $WEATHER_API_KEY" https://httpbin.org/status/401)
echo "weather API status: $status"
[ "$status" = 200 ] || exit 1

import axios from "axios";

const api = axios.create({
  baseURL: process.env.PAYMENTS_API_URL || "http://127.0.0.1:9",
  headers: { Authorization: `Bearer ${process.env.PAYMENTS_KEY}` },
});

try {
  const res = await api.post("/v1/charges/sync", {});
  console.log("synced", res.data);
} catch (err) {
  console.error("sync failed:", err);
  process.exit(1);
}
